def transform(grid):
 h,w=len(grid),len(grid[0])
 def comps(cells):
  cells=set(cells); out=[]
  while cells:
   p=cells.pop(); s={p}; stack=[p]
   while stack:
    r,c=stack.pop()
    for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
     if q in cells: cells.remove(q);s.add(q);stack.append(q)
   out.append(s)
  return out
 colors=set(x for row in grid for x in row)-{0,5}
 out=[row[:] for row in grid]
 templates=[]
 for color in colors:
  for s in comps((r,c) for r in range(h) for c in range(w) if grid[r][c]==color):
   mr=min(r for r,c in s);mc=min(c for r,c in s)
   templates.append((color,{(r-mr,c-mc) for r,c in s}))
  for r in range(h):
   for c in range(w):
    if grid[r][c]==color: out[r][c]=0
 total=sum(len(s) for col,s in templates)
 for component in comps((r,c) for r in range(h) for c in range(w) if grid[r][c]==5):
  if len(component)!=total: continue
  def solve(i,remaining,paint):
   if i==len(templates): return paint if not remaining else None
   color,shape=templates[i]; anchor=min(shape)
   for p in sorted(remaining):
    dr,dc=p[0]-anchor[0],p[1]-anchor[1]
    placed={(r+dr,c+dc) for r,c in shape}
    if placed<=remaining:
     ans=solve(i+1,remaining-placed,paint+[(color,placed)])
     if ans is not None:return ans
   return None
  ans=solve(0,component,[])
  if ans is not None:
   for color,placed in ans:
    for r,c in placed:out[r][c]=color
 return out

